// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    Reverter r;

    function setUp() public {
        c = new ReentrancyDAO();
        r = new Reverter();
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1 wei, 1000 ether);
        vm.deal(address(r), amount);
        vm.prank(address(r));
        c.deposit{value: amount}();
        bool ok;
        vm.prank(address(r));
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok && address(c).balance == amount, "failed transfer must revert and preserve balance");
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
